<script setup>
import { onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { collectionApi } from '@/services/collection.service'
const route=useRoute(),collection=ref(null),error=ref(''),message=ref(''),sectionTitle=ref(''),documentForm=reactive({documentType:'Sheet',documentId:'',sectionId:''})
async function load(){try{collection.value=await collectionApi.detail(route.params.id)}catch(cause){error.value=cause.message}}
async function update(){try{collection.value=await collectionApi.update(collection.value.id,{name:collection.value.name,description:collection.value.description,visibility:collection.value.visibility});message.value='บันทึกข้อมูลแล้ว'}catch(cause){error.value=cause.message}}
async function addSection(){try{collection.value=await collectionApi.addSection(collection.value.id,sectionTitle.value);sectionTitle.value=''}catch(cause){error.value=cause.message}}
async function removeSection(section){try{collection.value=await collectionApi.removeSection(collection.value.id,section.id)}catch(cause){error.value=cause.message}}
async function renameSection(section){try{collection.value=await collectionApi.renameSection(collection.value.id,section.id,section.title)}catch(cause){error.value=cause.message}}
async function addDocument(){try{collection.value=await collectionApi.addDocument(collection.value.id,{...documentForm});documentForm.documentId=''}catch(cause){error.value=cause.message}}
async function removeDocument(document){try{collection.value=await collectionApi.removeDocument(collection.value.id,document)}catch(cause){error.value=cause.message}}
function move(array,index,delta){const target=index+delta;if(target<0||target>=array.length)return;[array[index],array[target]]=[array[target],array[index]]}
function moveDocument(document,sectionId){document.sectionId=sectionId||null;for(const section of collection.value.sections)section.documents=section.documents.filter(item=>item!==document);collection.value.unsectioned=collection.value.unsectioned.filter(item=>item!==document);(sectionId?collection.value.sections.find(section=>section.id===sectionId).documents:collection.value.unsectioned).push(document)}
async function saveOrder(){try{collection.value=await collectionApi.saveOrder(collection.value.id,{expectedVersion:collection.value.version,sections:collection.value.sections.map(section=>section.id),documents:[...collection.value.unsectioned,...collection.value.sections.flatMap(section=>section.documents)].map(document=>({documentType:document.documentType,documentId:document.documentId,sectionId:document.sectionId||null}))});message.value='บันทึกลำดับแล้ว'}catch(cause){error.value=cause.message}}
function cover(event){const file=event.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=async()=>{try{collection.value=await collectionApi.uploadCover(collection.value.id,{fileName:file.name,fileData:String(reader.result)})}catch(cause){error.value=cause.message}};reader.readAsDataURL(file)}
async function removeCover(){try{collection.value=await collectionApi.removeCover(collection.value.id)}catch(cause){error.value=cause.message}}
onMounted(load)
</script>
<template><section v-if="collection" class="page-panel"><div class="panel__header"><div><p class="eyebrow">Collection editor</p><h1>{{ collection.name }}</h1><p>{{ collection.collectionType }}<span v-if="collection.courseCode"> · {{ collection.courseCode }}</span> · version {{ collection.version }}</p></div><RouterLink class="button button--ghost" to="/dashboard/collections">กลับ</RouterLink></div><p v-if="error" class="form-error" role="alert">{{ error }}</p><p v-if="message" class="form-success" role="status">{{ message }}</p>
<form class="form" @submit.prevent="update"><label>ชื่อ<input v-model="collection.name" maxlength="120" required></label><label>คำอธิบาย<textarea v-model="collection.description" maxlength="2000" /></label><label>การมองเห็น<select v-model="collection.visibility"><option value="AUTHENTICATED">ผู้ใช้ที่เข้าสู่ระบบ</option><option value="PRIVATE">ส่วนตัว</option></select></label><label>ภาพปก PNG/JPEG (ไม่เกิน 5 MB)<input type="file" accept="image/png,image/jpeg" @change="cover"></label><button v-if="collection.hasCover" type="button" class="button button--ghost" @click="removeCover">ลบภาพปก</button><button class="button button--primary">บันทึกข้อมูล</button></form>
<section class="content-section"><div class="section-heading"><h2>Sections และลำดับ</h2><button class="button button--primary button--small" @click="saveOrder">บันทึกลำดับ</button></div><form class="button-row" @submit.prevent="addSection"><input v-model="sectionTitle" maxlength="120" placeholder="ชื่อ Section" required><button class="button button--ghost">เพิ่ม Section</button></form>
<article class="collection-section"><h3>ไม่มี Section</h3><div v-for="(document,index) in collection.unsectioned" :key="`${document.documentType}:${document.documentId}`" class="collection-item"><span>{{ document.title }} · {{ document.courseCode }}</span><div class="button-row"><button class="button button--ghost button--small" :disabled="index===0" aria-label="เลื่อนเอกสารขึ้น" @click="move(collection.unsectioned,index,-1)">↑</button><button class="button button--ghost button--small" :disabled="index===collection.unsectioned.length-1" aria-label="เลื่อนเอกสารลง" @click="move(collection.unsectioned,index,1)">↓</button><select :value="document.sectionId||''" aria-label="ย้าย Section" @change="moveDocument(document,$event.target.value)"><option value="">ไม่มี Section</option><option v-for="section in collection.sections" :key="section.id" :value="section.id">{{ section.title }}</option></select><button class="button button--ghost button--small" @click="removeDocument(document)">นำออก</button></div></div></article>
<article v-for="(section,index) in collection.sections" :key="section.id" class="collection-section"><div class="section-heading"><input v-model="section.title" @change="renameSection(section)"><div class="button-row"><button class="button button--ghost button--small" :disabled="index===0" aria-label="เลื่อน Section ขึ้น" @click="move(collection.sections,index,-1)">↑</button><button class="button button--ghost button--small" :disabled="index===collection.sections.length-1" aria-label="เลื่อน Section ลง" @click="move(collection.sections,index,1)">↓</button><button class="button button--ghost button--small" @click="removeSection(section)">ลบ Section</button></div></div><div v-for="(document,documentIndex) in section.documents" :key="`${document.documentType}:${document.documentId}`" class="collection-item"><span>{{ document.title }} · {{ document.courseCode }}</span><div class="button-row"><button class="button button--ghost button--small" :disabled="documentIndex===0" @click="move(section.documents,documentIndex,-1)">↑</button><button class="button button--ghost button--small" :disabled="documentIndex===section.documents.length-1" @click="move(section.documents,documentIndex,1)">↓</button><select :value="section.id" @change="moveDocument(document,$event.target.value)"><option value="">ไม่มี Section</option><option v-for="target in collection.sections" :key="target.id" :value="target.id">{{ target.title }}</option></select><button class="button button--ghost button--small" @click="removeDocument(document)">นำออก</button></div></div></article></section>
<form class="form" @submit.prevent="addDocument"><h2>เพิ่มเอกสารที่เผยแพร่แล้ว</h2><div class="form-grid"><label>ประเภท<select v-model="documentForm.documentType"><option>Sheet</option><option>Lecture</option></select></label><label>Document ID<input v-model.trim="documentForm.documentId" required></label><label>Section<select v-model="documentForm.sectionId"><option value="">ไม่มี Section</option><option v-for="section in collection.sections" :key="section.id" :value="section.id">{{ section.title }}</option></select></label></div><button class="button button--primary">เพิ่มเอกสาร</button></form></section><section v-else class="page-panel"><p v-if="error" class="form-error">{{ error }}</p><p v-else>กำลังโหลด…</p></section></template>
